            if(node==null)for(android.view.accessibility.AccessibilityWindowInfo window:automation.getWindows()){
                AccessibilityNodeInfo windowRoot=window.getRoot();if(!packageIs(windowRoot,"cc.huevia"))continue;node=findNode(windowRoot,text);if(node!=null)break;
            }
